def write():
    (OUT/'references.json').write_text(json.dumps(refs,ensure_ascii=False,indent=2)+'\n')
    with (OUT/'search_log.tsv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=list(searches[0]),delimiter='\t');w.writeheader();w.writerows(searches)
    with (OUT/'references.bib').open('w') as f:
        for r in refs:
            f.write('@misc{'+r['key']+',\n')
            for k in ['author','title','year','url','doi','eprint','booktitle','series','volume','pages','note']:
                if r.get(k) and not(k=='year' and r.get('year_uncertain')):
                    f.write('  '+k+' = {'+r[k]+'},\n')
            f.write('  annote = {'+r['scope'].replace('{','(').replace('}',')')+'}\n}\n\n')
    print(datetime.datetime.now(datetime.timezone.utc).isoformat(), 'references',len(refs),'search batches',len(searches))
if __name__=='__main__':write()
